import { ValidationError } from '../errors/ApplicationError';

/** Structural checks for untrusted input before it becomes a command. */

export function requireRecord(input: unknown, what: string): Record<string, unknown> {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new ValidationError(`${what} must be a JSON object`);
  }
  return input as Record<string, unknown>;
}

export function requireString(record: Record<string, unknown>, field: string): string {
  const value = record[field];
  if (typeof value !== 'string' || value.trim().length === 0) {
    throw new ValidationError(`'${field}' must be a non-empty string`);
  }
  return value.trim();
}

export function requireInteger(record: Record<string, unknown>, field: string): number {
  const value = record[field];
  if (typeof value !== 'number' || !Number.isSafeInteger(value)) {
    throw new ValidationError(`'${field}' must be an integer`);
  }
  return value;
}

export function requireArray(record: Record<string, unknown>, field: string): unknown[] {
  const value = record[field];
  if (!Array.isArray(value)) {
    throw new ValidationError(`'${field}' must be an array`);
  }
  return value;
}

